1	// Command payflow is the 链上支付与结算编排平台 entry point.
2	package main
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11	
12		"github.com/gzhysuiioo/payflow-settlement/payflow"
13	)
14	
15	func main() {
16		os.Exit(runCLI(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
17	}
18	
19	const versionString = "payflow 0.2.0"
20	
21	func runCLI(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
22		if len(args) == 0 {
23			return runDemo(stdout)
24		}
25		switch args[0] {
26		case "demo":
27			return runDemo(stdout)
28		case "version":
29			fmt.Fprintln(stdout, versionString)
30			return 0
31		case "help", "-h", "--help":
32			usage(stdout)
33			return 0
34		case "init":
35			return cmdInit(args[1:], stdin, stdout, stderr)
36		case "submit":
37			return cmdSubmit(args[1:], stdin, stdout, stderr)
38		case "refund":
39			return cmdRefund(args[1:], stdin, stdout, stderr)
40		case "query":
41			return cmdQuery(args[1:], stdout, stderr)
42		case "reconcile":
43			return cmdReconcile(args[1:], stdin, stdout, stderr)
44		default:
45			fmt.Fprintf(stderr, "unknown command %q\n", args[0])
46			usage(stderr)
47			return 2
48		}
49	}
50	
51	func usage(w io.Writer) {
52		fmt.Fprintln(w, "usage: payflow <command> [flags]")
53		fmt.Fprintln(w, "")
54		fmt.Fprintln(w, "commands:")
55		fmt.Fprintln(w, "  init       initialize a ledger with starting balances")
56		fmt.Fprintln(w, "  submit     submit a JSON payment batch against a ledger")
57		fmt.Fprintln(w, "  refund     submit a JSON full-refund batch against a ledger")
58		fmt.Fprintln(w, "  query      print balances, settlement and refund records of a ledger")
59		fmt.Fprintln(w, "  reconcile  reconcile an ordered JSON flow against a ledger")
60		fmt.Fprintln(w, "  demo       run the in-memory settlement demo")
61		fmt.Fprintln(w, "  version    print version")
62		fmt.Fprintln(w, "  help       show this help")
63		fmt.Fprintln(w, "")
64		fmt.Fprintln(w, "ledger flags (init/submit/refund/query/reconcile):")
65		fmt.Fprintln(w, "  -l, --ledger <path>   ledger file path (required)")
66		fmt.Fprintln(w, "  -f, --file <path>     JSON input file (init/submit/refund/reconcile; default: stdin)")
67		fmt.Fprintln(w, "")
68		fmt.Fprintln(w, "submit flags:")
69		fmt.Fprintln(w, "  --dry-run             preview settlement results without writing the ledger")
70		fmt.Fprintln(w, "")
71		fmt.Fprintln(w, "reconcile range flags (seq bounds, after < seq <= through; default: full history):")
72		fmt.Fprintln(w, "  --payment-after <n>    payment seq lower bound (exclusive)")
73		fmt.Fprintln(w, "  --payment-through <n>  payment seq upper bound (inclusive)")
74		fmt.Fprintln(w, "  --refund-after <n>     refund seq lower bound (exclusive)")
75		fmt.Fprintln(w, "  --refund-through <n>   refund seq upper bound (inclusive)")
76	}
77	
78	// initRequest 是 init 的输入：{"balances":[...]}。
79	// Balance 用指针解码，只为区分“未提供/null”与显式写出的 0：
80	// 缺失或 null 的余额必须整次拒绝，不能默默当成 0 落账；显式 0 仍是合法余额。
81	// 校验通过后转换为 payflow.BalanceInit，库的公开数据写法不变。
82	type initRequest struct {
83		Balances []balanceInitJSON `json:"balances"`
84	}
85	
86	type balanceInitJSON struct {
87		Account string `json:"account"`
88		Asset   string `json:"asset"`
89		Balance *int64 `json:"balance"`
90	}
91	
92	// toBalanceInits 把解码后的余额列表转换为库的 BalanceInit 列表。
93	// 任一条目未明确提供 balance（缺省或 null）即返回错误，下标从 0 开始；
94	// 调用方必须整次拒绝，不得用部分合法条目初始化账本。
95	func toBalanceInits(list []balanceInitJSON) ([]payflow.BalanceInit, error) {
96		out := make([]payflow.BalanceInit, len(list))
97		for i, b := range list {
98			if b.Balance == nil {
99				return nil, fmt.Errorf("initial balance %d (%s/%s): balance must be provided explicitly as a non-negative int64 (use 0 for an intentional zero balance)", i, b.Account, b.Asset)
100			}
101			out[i] = payflow.BalanceInit{Account: b.Account, Asset: b.Asset, Balance: *b.Balance}
102		}
103		return out, nil
104	}
105	
106	type errorEnvelope struct {
107		Error struct {
108			Kind    string `json:"kind"`
109			Message string `json:"message"`
110		} `json:"error"`
111	}
112	
113	func failEnvelope(stderr io.Writer, kind, message string) int {
114		env := errorEnvelope{}
115		env.Error.Kind = kind
116		env.Error.Message = message
117		writeJSON(stderr, env)
118		return 1
119	}
120	
121	func failWithError(stderr io.Writer, err error) int {
122		return failEnvelope(stderr, payflow.KindOf(err), err.Error())
123	}
124	
125	// writeJSON 把 v 以缩进 JSON 加末尾换行写出。任一写入返回错误、或实际写出
126	// 字节少于请求字节（短写，即使未同时返回错误），都返回错误；调用方必须据此
127	// 判定输出失败，不能再当作成功。
128	func writeJSON(w io.Writer, v any) error {
129		data, err := json.MarshalIndent(v, "", "  ")
130		if err != nil {
131			fmt.Fprintf(w, `{"error":{"kind":"storage_error","message":%q}}`+"\n", err.Error())
132			return err
133		}
134		if err := writeFull(w, data); err != nil {
135			return err
136		}
137		return writeFull(w, []byte("\n"))
138	}
139	
140	// writeFull 要求一次写完 data：短写按 io.ErrShortWrite 处理。
141	func writeFull(w io.Writer, data []byte) error {
142		n, err := w.Write(data)
143		if err != nil {
144			return err
145		}
146		if n != len(data) {
147			return io.ErrShortWrite
148		}
149		return nil
150	}
151	
152	// failOutput 报告结果输出阶段（写标准输出）的失败：错误信封只写标准错误，
153	// 不往可能已留有部分内容的标准输出再补成功响应或混入错误 JSON。
154	func failOutput(stderr io.Writer, err error) int {
155		return failEnvelope(stderr, payflow.ErrStorage, "write result to standard output: "+err.Error())
156	}
157	
158	// ledgerFlagSet 构造 -l/--ledger、-f/--file 标志。
159	func ledgerFlagSet(name string) (*flag.FlagSet, *string, *string) {
160		fs := flag.NewFlagSet(name, flag.ContinueOnError)
161		fs.SetOutput(io.Discard)
162		var ledgerPath, inputFile string
163		fs.StringVar(&ledgerPath, "ledger", "", "ledger file path")
164		fs.StringVar(&ledgerPath, "l", "", "ledger file path (shorthand)")
165		fs.StringVar(&inputFile, "file", "", "JSON input file (default stdin)")
166		fs.StringVar(&inputFile, "f", "", "JSON input file (shorthand)")
167		return fs, &ledgerPath, &inputFile
168	}
169	
170	func readInput(path string, stdin io.Reader) ([]byte, error) {
171		if path == "" {
172			return io.ReadAll(stdin)
173		}
174		return os.ReadFile(path)
175	}
176	
177	func cmdInit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
178		fs, ledgerPath, inputFile := ledgerFlagSet("init")
179		if err := fs.Parse(args); err != nil {
180			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
181		}
182		if *ledgerPath == "" {
183			return failEnvelope(stderr, payflow.ErrInvalid, "init requires --ledger <path>")
184		}
185		raw, err := readInput(*inputFile, stdin)
186		if err != nil {
187			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
188		}
189		var req initRequest
190		dec := json.NewDecoder(bytes.NewReader(raw))
191		if err := dec.Decode(&req); err != nil {
192			return failEnvelope(stderr, payflow.ErrInvalid, "parse init JSON: "+err.Error())
193		}
194		if err := requireEOF(dec, "init"); err != nil {
195			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
196		}
197		// 先整体校验余额是否都明确给出：任一缺失/null 即整次拒绝，
198		// 不创建账本，也不把前面的合法条目单独落账。
199		inits, err := toBalanceInits(req.Balances)
200		if err != nil {
201			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
202		}
203		if err := payflow.CreateLedger(*ledgerPath, inits); err != nil {
204			return failWithError(stderr, err)
205		}
206		writeJSON(stdout, map[string]any{
207			"status":   "initialized",
208			"ledger":   *ledgerPath,
209			"accounts": len(inits),
210		})
211		return 0
212	}
213	
214	func cmdSubmit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
215		fs, ledgerPath, inputFile := ledgerFlagSet("submit")
216		var dryRun bool
217		fs.BoolVar(&dryRun, "dry-run", false, "preview settlement results without writing the ledger")
218		if err := fs.Parse(args); err != nil {
219			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
220		}
221		if *ledgerPath == "" {
222			return failEnvelope(stderr, payflow.ErrInvalid, "submit requires --ledger <path>")
223		}
224		raw, err := readInput(*inputFile, stdin)
225		if err != nil {
226			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
227		}
228		var batch payflow.FeeBatch
229		dec := json.NewDecoder(bytes.NewReader(raw))
230		if err := dec.Decode(&batch); err != nil {
231			return failEnvelope(stderr, payflow.ErrInvalid, "parse batch JSON: "+err.Error())
232		}
233		if err := requireEOF(dec, "submit"); err != nil {
234			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
235		}
236	
237		l, err := payflow.Open(*ledgerPath)
238		if err != nil {
239			return failWithError(stderr, err)
240		}
241		defer l.Close()
242	
243		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
244		// --dry-run 只预测业务结果：不写入账本，输出带 dry_run:true 标记。
245		// 结果输出阶段失败（写错误或短写，含末尾换行）：退出码 1，错误信封只写
246		// 标准错误；已落账的付款不回滚，预览也保持账本不变。
247		if dryRun {
248			result, err := l.Preview(batch)
249			if err != nil {
250				return failWithError(stderr, err)
251			}
252			if err := writeJSON(stdout, result); err != nil {
253				return failOutput(stderr, err)
254			}
255			return 0
256		}
257		result, err := l.Submit(batch)
258		if err != nil {
259			return failWithError(stderr, err)
260		}
261		if err := writeJSON(stdout, result); err != nil {
262			return failOutput(stderr, err)
263		}
264		return 0
265	}
266	
267	func cmdRefund(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
268		fs, ledgerPath, inputFile := ledgerFlagSet("refund")
269		if err := fs.Parse(args); err != nil {
270			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
271		}
272		if *ledgerPath == "" {
273			return failEnvelope(stderr, payflow.ErrInvalid, "refund requires --ledger <path>")
274		}
275		raw, err := readInput(*inputFile, stdin)
276		if err != nil {
277			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
278		}
279		var batch payflow.RefundBatch
280		dec := json.NewDecoder(bytes.NewReader(raw))
281		if err := dec.Decode(&batch); err != nil {
282			return failEnvelope(stderr, payflow.ErrInvalid, "parse refund batch JSON: "+err.Error())
283		}
284		if err := requireEOF(dec, "refund"); err != nil {
285			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
286		}
287	
288		l, err := payflow.Open(*ledgerPath)
289		if err != nil {
290			return failWithError(stderr, err)
291		}
292		defer l.Close()
293	
294		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
295		// 结果输出阶段失败（写错误或短写，含末尾换行）：退出码 1，错误信封只写
296		// 标准错误；已落账的退款不回滚，批次不会重放。
297		result, err := l.Refund(batch)
298		if err != nil {
299			return failWithError(stderr, err)
300		}
301		if err := writeJSON(stdout, result); err != nil {
302			return failOutput(stderr, err)
303		}
304		return 0
305	}
306	
307	func cmdQuery(args []string, stdout, stderr io.Writer) int {
308		fs, ledgerPath, _ := ledgerFlagSet("query")
309		if err := fs.Parse(args); err != nil {
310			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
311		}
312		if *ledgerPath == "" {
313			return failEnvelope(stderr, payflow.ErrInvalid, "query requires --ledger <path>")
314		}
315		l, err := payflow.Open(*ledgerPath)
316		if err != nil {
317			return failWithError(stderr, err)
318		}
319		defer l.Close()
320		snap, err := l.Query()
321		if err != nil {
322			return failWithError(stderr, err)
323		}
324		writeJSON(stdout, snap)
325		return 0
326	}
327	
328	func cmdReconcile(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
329		fs, ledgerPath, inputFile := ledgerFlagSet("reconcile")
330		// 序号边界：after 排除下界、through 包含上界（after < seq <= through）。
331		// 用指针区分“未提供”与显式给出的 0：未提供时由库取缺省值（下界 0、
332		// 上界为该类记录的最大成功序号）。
333		var paymentAfter, paymentThrough, refundAfter, refundThrough int64
334		fs.Int64Var(&paymentAfter, "payment-after", 0, "payment seq lower bound (exclusive)")
335		fs.Int64Var(&paymentThrough, "payment-through", 0, "payment seq upper bound (inclusive)")
336		fs.Int64Var(&refundAfter, "refund-after", 0, "refund seq lower bound (exclusive)")
337		fs.Int64Var(&refundThrough, "refund-through", 0, "refund seq upper bound (inclusive)")
338		if err := fs.Parse(args); err != nil {
339			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
340		}
341		if *ledgerPath == "" {
342			return failEnvelope(stderr, payflow.ErrInvalid, "reconcile requires --ledger <path>")
343		}
344		raw, err := readInput(*inputFile, stdin)
345		if err != nil {
346			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
347		}
348		// 先严格解析全部输入：任一条目不合法则整次拒绝，退出码 1，不输出部分报告。
349		entries, err := payflow.ParseReconcileRequest(raw)
350		if err != nil {
351			return failWithError(stderr, err)
352		}
353	
354		bounds := payflow.ReconcileBounds{}
355		fs.Visit(func(f *flag.Flag) {
356			switch f.Name {
357			case "payment-after":
358				v := paymentAfter
359				bounds.PaymentAfter = &v
360			case "payment-through":
361				v := paymentThrough
362				bounds.PaymentThrough = &v
363			case "refund-after":
364				v := refundAfter
365				bounds.RefundAfter = &v
366			case "refund-through":
367				v := refundThrough
368				bounds.RefundThrough = &v
369			}
370		})
371	
372		l, err := payflow.Open(*ledgerPath)
373		if err != nil {
374			return failWithError(stderr, err)
375		}
376		defer l.Close()
377	
378		// 对账只读：不改余额、历史或账本文件。边界非法同样整次拒绝、不输出部分
379		// 报告；输入有差异仍是正常结果，退出码 0。
380		report, err := l.ReconcileFlowRanged(entries, bounds)
381		if err != nil {
382			return failWithError(stderr, err)
383		}
384		writeJSON(stdout, report)
385		return 0
386	}
387	
388	// requireEOF 拒绝 JSON 文档之后的尾随内容。
389	func requireEOF(dec *json.Decoder, what string) error {
390		if tok, err := dec.Token(); err != io.EOF {
391			if err == nil {
392				return fmt.Errorf("%s: unexpected trailing content after JSON document (token %v)", what, tok)
393			}
394			return fmt.Errorf("%s: %v", what, err)
395		}
396		return nil
397	}
398	
399	func runDemo(stdout io.Writer) int {
400		intents := []payflow.Intent{
401			{ID: "pay-1", Account: "aa-1", Paymaster: "pm-1", Amount: 1500, Asset: "usdc", Nonce: 1, State: "pending"},
402			{ID: "pay-2", Account: "aa-1", Paymaster: "pm-1", Amount: 900, Asset: "usdc", Nonce: 2, State: "pending"},
403		}
404		spent := map[string]bool{}
405		var settlements []payflow.Settlement
406		for _, intent := range intents {
407			settlement := payflow.Execute(intent, 30, spent, 2000)
408			settlements = append(settlements, settlement)
409			fmt.Fprintf(stdout, "intent=%s status=%s charged=%d reason=%s\n", settlement.Intent, settlement.Status, settlement.Charged, settlement.Reason)
410		}
411		duplicate := payflow.Execute(intents[0], 30, spent, 2000)
412		fmt.Fprintf(stdout, "duplicate of %s status=%s reason=%s\n", duplicate.Intent, duplicate.Status, duplicate.Reason)
413		fmt.Fprintln(stdout, "reconciliation gaps:", payflow.Reconcile(intents, settlements))
414		return 0
415	}
