1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"reflect"
8		"testing"
9	)
10	
11	// 本文件为 Submit 返回结果与账本结算事实之间的独立性提供回归保障。
12	// 首次付款成功项（settled）与幂等重复项（duplicate）都会向调用者提供完整
13	// 结算记录（*Record），本文件围绕这两种结果锁定：
14	//
15	//  1. 空间独立：调用者可以任意修改自己手里的成功/重复结果（返回项的编号、状态、
16	//     说明，以及记录中的编号、账户、资产、付款方、金额、nonce、费率、手续费、
17	//     扣款总额和成功序号），改动只能作用于这份结果：账本中的结算记录、真实余额
18	//     与付款去向都不变。
19	//  2. 判定独立：改大返回金额不能抬高可用余额，改编号不能释放已成功的付款编号，
20	//     改状态/说明不能影响后续 settled/duplicate/conflict/insufficient_balance
21	//     判定；只改返回数据不能新增成功记录，也不能触发账本文件改写。
22	//  3. 改对象不等于改请求：只改返回对象不产生任何业务变更；原请求重提仍返回
23	//     duplicate 和最初的完整记录、不再扣款；用原编号提交字段已合法改变的请求
24	//     仍返回 conflict，不能因为调用者改过旧结果就接受新内容。
25	//  4. 结果之间彼此独立：同批次内的成功项与重复项、不同次调用取得的结果、
26	//     后续新付款前后保留的旧结果，各自持有可修改副本，编号、成功序号与金额
27	//     互不影响。
28	//
29	// 基础场景：账户原有 2000，付款 1500、费率 30 基点、指定付款方与 nonce，
30	// 手续费 4、扣款 1504、余额 496。
31	//
32	// 付款规则、公开接口、ItemResult/Record 的公开 JSON 字段与命令行输出均不在
33	// 本文件变更。
34	
35	// baseScenarioPayment 构造基础场景付款：aa/usdc 付款 1500，费率 30 基点，
36	// 付款方 pm-1、nonce 7。起始余额 2000 时手续费 4、扣款 1504、余 496。
37	func baseScenarioPayment(id string) PaymentIntent {
38		it := intent(id, "aa", "usdc", 1500)
39		it.Paymaster = "pm-1"
40		it.Nonce = 7
41		return it
42	}
43	
44	// baseScenarioRecord 是基础场景付款成功后账本应保留的真实记录；seq 由调用处
45	// 按成功先后给出。
46	func baseScenarioRecord(id string, seq int64) Record {
47		return Record{
48			ID: id, Account: "aa", Paymaster: "pm-1", Asset: "usdc",
49			Amount: 1500, Nonce: 7, FeeBps: 30, Fee: 4, Charged: 1504, Seq: seq,
50		}
51	}
52	
53	// corruptItemResult 像调用者为自己展示所做的那样，破坏性改写一份付款结果：
54	// 返回项的编号、状态、说明，以及完整记录的全部字段一律换成伪造值
55	// （金额改小、去向改成 zz/btc、序号改成 77）。
56	func corruptItemResult(r *ItemResult) {
57		r.ID = "HACK-ID"
58		r.Status = "forged-status"
59		r.Reason = "forged reason"
60		if r.Record == nil {
61			return
62		}
63		r.Record.ID = "HACK-REC"
64		r.Record.Account = "zz"
65		r.Record.Paymaster = "fake-pm"
66		r.Record.Asset = "btc"
67		r.Record.Amount = 1
68		r.Record.Nonce = 99
69		r.Record.FeeBps = 9999
70		r.Record.Fee = 9
