79		if got.ID != want.ID {
80			t.Fatalf("id=%q want %q: %+v", got.ID, want.ID, got)
81		}
82		if got.Status != wantStatus {
83			t.Fatalf("status=%s want %s: %+v", got.Status, wantStatus, got)
