96	// TestSubmitSuccessResultEditsStayPrivate 覆盖核心隔离：一笔带手续费、付款方和
97	// nonce 的付款首次成功后，调用者留存返回结果并任意改写（返回项编号、状态、
98	// 说明，以及记录的编号、账户、资产、付款方、金额、nonce、费率、手续费、扣款
99	// 总额和成功序号），账本中的结算事实必须原样保留；后续全额退款只能按真实原
100	// 记录退回原账户、原资产。
101	func TestSubmitSuccessResultEditsStayPrivate(t *testing.T) {
102		path := newTestLedger(t, []BalanceInit{
103			{Account: "aa", Asset: "usdc", Balance: 2000},
104			{Account: "bb", Asset: "usdc", Balance: 800},
105			{Account: "aa", Asset: "eth", Balance: 100},
106		})
107		l := openOrFail(t, path)
108	
109		// 首次成功：1500 本金 + 30bps 手续费 4，共扣 1504，aa/usdc 余 496。
110		first := mustSettle(t, l, 30, baseScenarioPayment("p1"))
111		wantP1 := baseScenarioRecord("p1", 1)
112		assertItemResult(t, first, StatusSettled, "", wantP1)
113		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
114			t.Fatalf("balance after settle=%d want 496", bal)
115		}
116	
117		// 公开 JSON 格式回归：成功结果携带完整记录，键名固定；成功项不带说明。
118		raw, err := json.Marshal(first)
119		if err != nil {
120			t.Fatal(err)
121		}
122		for _, frag := range []string{
123			`"id":"p1"`, `"status":"settled"`, `"record":{`,
124			`"account":"aa"`, `"paymaster":"pm-1"`, `"asset":"usdc"`,
125			`"amount":1500`, `"nonce":7`, `"fee_bps":30`, `"fee":4`,
126			`"charged":1504`, `"seq":1`,
127		} {
128			if !bytes.Contains(raw, []byte(frag)) {
129				t.Fatalf("success result JSON missing %s:\n%s", frag, raw)
130			}
131		}
132		if bytes.Contains(raw, []byte(`"reason"`)) {
133			t.Fatalf("settled result must not carry a reason:\n%s", raw)
134		}
135	
136		// 记录调用者改写之前的账本文件字节：单纯修改返回数据不能改写账本文件。
137		fileBefore, err := os.ReadFile(path)
138		if err != nil {
139			t.Fatal(err)
140		}
141	
142		// 调用者留存并破坏性改写手里的结果（金额改小、去向改成 zz/btc、序号改成 77）。
143		corruptItemResult(&first)
144	
145		// 1. 账本查询仍看到最初成功的那笔付款，字段逐字不变；只有一条结算记录。
146		snap := mustQuery(t, l)
147		if len(snap.Settlements) != 1 {
148			t.Fatalf("settlement count=%d want 1: %+v", len(snap.Settlements), snap.Settlements)
149		}
150		if snap.Settlements[0] != wantP1 {
151			t.Fatalf("real settlement altered by caller edit:\n got %+v\nwant %+v",
152				snap.Settlements[0], wantP1)
153		}
154	
155		// 2. 真实余额仍是 496：改小返回金额不能把钱补回来，改去向也不能动其他组合。
156		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
157			t.Fatalf("balance changed after editing result: %d want 496", bal)
158		}
159		if bal, _ := l.Balance("zz", "btc"); bal != 0 {
160			t.Fatalf("payment leaked to forged destination: zz/btc=%d want 0", bal)
161		}
162		if bal, _ := l.Balance("bb", "usdc"); bal != 800 {
163			t.Fatalf("unrelated account balance changed: bb/usdc=%d want 800", bal)
164		}
165	
166		// 3. 超过真实余额 496 的新付款仍返回 insufficient_balance，且失败不留记录。
167		overspend := mustSettle(t, l, 0, intent("p-over", "aa", "usdc", 497))
168		if overspend.Status != StatusFunds {
169			t.Fatalf("want insufficient_balance against the real balance, got %+v", overspend)
170		}
171		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
172			t.Fatalf("failed payment changed balance: %d want 496", bal)
173		}
174		if len(mustQuery(t, l).Settlements) != 1 {
175			t.Fatalf("a failed payment must not add a settlement")
176		}
177	
178		// 4. 只改返回记录不释放已成功编号：原请求重提仍 duplicate 且携带真实原记录，
179		//    不再扣款。
180		dup := mustSettle(t, l, 30, baseScenarioPayment("p1"))
181		assertItemResult(t, dup, StatusDuplicate, reasonDuplicate, wantP1)
182		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
183			t.Fatalf("duplicate charged again: bal=%d want 496", bal)
184		}
185	
186		// 查询、失败付款、重复提交与调用者改写都没有触发账本文件改写。
187		fileAfter, err := os.ReadFile(path)
188		if err != nil {
189			t.Fatal(err)
190		}
191		if !bytes.Equal(fileBefore, fileAfter) {
192			t.Fatalf("ledger file changed without a successful charge:\nbefore=%s\nafter =%s",
193				fileBefore, fileAfter)
194		}
195	
196		// 5. 之后正常申请全额退款：必须按账本里的原记录把 1504 退回原账户 aa、
197		//    原资产 usdc，而不是采用返回对象里伪造的 zz/btc 或伪造金额。
198		ref := mustRefundOne(t, l, "r1", "p1", "full refund")
199		wantR1 := RefundRecord{
200			ID: "r1", SettlementID: "p1", Reason: "full refund",
201			Account: "aa", Asset: "usdc", Amount: 1500, Fee: 4, Charged: 1504,
202			AfterSeq: 1, Seq: 1,
203		}
204		assertRefundResultRecord(t, ref, StatusRefundSuccess, wantR1)
205		if bal, _ := l.Balance("aa", "usdc"); bal != 2000 {
206			t.Fatalf("refund credit=%d want 2000", bal)
207		}
208		if bal, _ := l.Balance("zz", "btc"); bal != 0 {
209			t.Fatalf("refund leaked to forged destination: zz/btc=%d want 0", bal)
210		}
211		if bal, _ := l.Balance("bb", "usdc"); bal != 800 {
212			t.Fatalf("refund leaked to another account: bb/usdc=%d want 800", bal)
213		}
214	
215		// 退款后编号仍被真实结算占用：原请求重提依旧 duplicate、携带原记录、不扣款。
216		again := mustSettle(t, l, 30, baseScenarioPayment("p1"))
217		assertItemResult(t, again, StatusDuplicate, reasonDuplicate, wantP1)
218		if bal, _ := l.Balance("aa", "usdc"); bal != 2000 {
219			t.Fatalf("retry after refund charged again: bal=%d want 2000", bal)
220		}
221		if len(mustQuery(t, l).Settlements) != 1 {
222			t.Fatalf("retries must not add settlement records")
223		}
224	}
