846		if s := Execute(Intent{ID: "a", State: "done", Amount: 0}, 10001, spent, 0); s.Status != "rejected" || s.Reason != reasonNotPending {
847			t.Fatalf("not-pending must take precedence: %+v", s)
848		}
849		// pending 但已结算优先于金额、费率检查。
850		if s := Execute(Intent{ID: "a", State: "pending", Amount: 0}, 10001, spent, 0); s.Status != "rejected" || s.Reason != reasonDuplicate {
851			t.Fatalf("duplicate must take precedence over amount/fee: %+v", s)
852		}
853	
854		// 金额不合法的编号修正后作为首次付款成功（而非 duplicate）。
855		fresh := map[string]bool{}
856		if s := Execute(Intent{ID: "p", State: "pending", Amount: 0}, 0, fresh, 100); s.Status != "rejected" {
857			t.Fatalf("zero amount rejected: %+v", s)
858		}
859		if s := Execute(Intent{ID: "p", State: "pending", Amount: 100}, 0, fresh, 100); s.Status != "settled" || s.Charged != 100 {
860			t.Fatalf("corrected amount must settle as first payment: %+v", s)
861		}
862	
863		// 余额不足失败后补足余额，同一编号仍可作为首次付款成功。
864		funds := map[string]bool{}
865		if s := Execute(Intent{ID: "q", State: "pending", Amount: 100}, 0, funds, 50); s.Status != "failed" {
866			t.Fatalf("insufficient: %+v", s)
867		}
868		if s := Execute(Intent{ID: "q", State: "pending", Amount: 100}, 0, funds, 100); s.Status != "settled" || s.Charged != 100 {
869			t.Fatalf("retry after top-up must settle as first payment: %+v", s)
870		}
871	}
