1262	// 并发：多个句柄并发退款，每笔原付款最多退回一次（唯一退款编号下恰一笔成功，
1263	// 其余 already_refunded），查询看不到半更新状态。
1264	func TestRefundConcurrentSettlesRefundOnce(t *testing.T) {
1265		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
1266		lc := openOrFail(t, path)
1267		if _, err := lc.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("only", "aa", "usdc", 1000)}}); err != nil {
1268			t.Fatal(err)
1269		}
1270	
1271		const n = 40
1272		var wg sync.WaitGroup
1273		c2 := map[string]int{}
1274		var m2 sync.Mutex
1275		for i := 0; i < n; i++ {
1276			i := i
1277			wg.Add(1)
1278			go func() {
1279				defer wg.Done()
1280				h, err := Open(path)
1281				if err != nil {
1282					t.Errorf("Open: %v", err)
1283					return
1284				}
1285				defer h.Close()
1286				rr, err := h.Refund(RefundBatch{Refunds: []RefundRequest{refundReq(fmt.Sprintf("rid-%d", i), "only", "x")}})
1287				if err != nil {
1288					t.Errorf("Refund: %v", err)
1289					return
1290				}
1291				m2.Lock()
1292				c2[rr.Results[0].Status]++
1293				m2.Unlock()
1294			}()
1295		}
1296		wg.Wait()
1297		if c2[StatusRefundSuccess] != 1 {
1298			t.Fatalf("refunded=%d want 1 (counts=%v)", c2[StatusRefundSuccess], c2)
1299		}
1300		if c2[StatusAlreadyRefunded] != n-1 {
1301			t.Fatalf("already_refunded=%d want %d (counts=%v)", c2[StatusAlreadyRefunded], n-1, c2)
1302		}
1303		snap, _ := lc.Query()
1304		if len(snap.Refunds) != 1 {
1305			t.Fatalf("refund records=%d want 1", len(snap.Refunds))
1306		}
1307		if bal, _ := lc.Balance("aa", "usdc"); bal != 1000 {
1308			t.Fatalf("balance=%d want 1000", bal)
1309		}
1310	}
