1387			"double refund": {finalBack, []Record{rec}, []RefundRecord{
1388				goodRF,
1389				func() RefundRecord { r := goodRF; r.ID = "r2"; r.Seq = 2; return r }(),
1390			}},
1391			"amount differs":      {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Amount = 299; r.Charged = 299 })},
1392			"charged differs":     {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Charged = 301 })},
1393			"asset differs":       {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.Asset = "eth" })},
