1396			"after_seq too large": {finalBack, []Record{rec}, mkRF(func(r *RefundRecord) { r.AfterSeq = 2 })},
1397			"balance mismatch":    {map[balanceKey]int64{k: 999}, []Record{rec}, mkRF(func(r *RefundRecord) {})},
1398		}
1399	
1400		// “duplicate refund id”：两笔不同结算各退一次，但两条退款记录共用编号 r1。
1401		rec2 := Record{ID: "p2", Account: "aa", Paymaster: "pm", Asset: "usdc", Amount: 1, Nonce: 2, FeeBps: 0, Fee: 0, Charged: 1, Seq: 2}
1402		rf2 := goodRF
