1408			final   map[balanceKey]int64
1409			records []Record
1410			refunds []RefundRecord
1411		}{
1412			final:   map[balanceKey]int64{k: 1000 - 1},
1413			records: []Record{rec, rec2},
1414			refunds: []RefundRecord{goodRF, rf2},
